from itertools import permutations

people = ['Avery', 'Blake', 'Harper', 'Sawyer']
colors = ['blue', 'green', 'white', 'yellow']
pets = ['bird', 'dog', 'fish', 'rabbit']
drinks = ['cocoa', 'coffee', 'milk', 'water']

for person_perm in permutations(people):
    for color_perm in permutations(colors):
        for pet_perm in permutations(pets):
            for drink_perm in permutations(drinks):
                houses = [None] * 5
                for i in range(4):
                    houses[i + 1] = {
                        'person': person_perm[i],
                        'color': color_perm[i],
                        'pet': pet_perm[i],
                        'drink': drink_perm[i]
                    }

                # Constraint 1: Blue house -> rabbit owner
                valid = True
                for p in range(1, 5):
                    if houses[p]['color'] == 'blue' and houses[p]['pet'] != 'rabbit':
                        valid = False
                        break
                if not valid:
                    continue

                # Constraint 2: Green house next to Blake
                blake_pos = None
                green_pos = None
                for p in range(1, 5):
                    if houses[p]['person'] == 'Blake':
                        blake_pos = p
                    if houses[p]['color'] == 'green':
                        green_pos = p

                if blake_pos is None or green_pos is None or abs(green_pos - blake_pos) != 1:
                    continue

                # Constraint 3: Sawyer immediately left of coffee drinker
                sawyer_pos = None
                coffee_pos = None
                for p in range(1, 5):
                    if houses[p]['person'] == 'Sawyer':
                        sawyer_pos = p
                    if houses[p]['drink'] == 'coffee':
                        coffee_pos = p

                if sawyer_pos is None or coffee_pos is None or coffee_pos - sawyer_pos != 1:
                    continue

                # Constraint 4: Cocoa drinker -> fish owner
                for p in range(1, 5):
                    if houses[p]['drink'] == 'cocoa' and houses[p]['pet'] != 'fish':
                        valid = False
                        break
                if not valid:
                    continue

                # Constraint 5: Blue house immediately left of Sawyer
                blue_pos = None
                for p in range(1, 5):
                    if houses[p]['color'] == 'blue':
                        blue_pos = p
                        break

                if blue_pos is None or sawyer_pos - blue_pos != 1:
                    continue

                # Constraint 6: Bird owner next to coffee drinker
                bird_pos = None
                for p in range(1, 5):
                    if houses[p]['pet'] == 'bird':
                        bird_pos = p
                        break

                if bird_pos is None or abs(bird_pos - coffee_pos) != 1:
                    continue

                # Constraint 7: Cocoa drinker immediately left of Avery
                cocoa_pos = None
                avery_pos = None
                for p in range(1, 5):
                    if houses[p]['drink'] == 'cocoa':
                        cocoa_pos = p
                    if houses[p]['person'] == 'Avery':
                        avery_pos = p

                if cocoa_pos is None or avery_pos is None or avery_pos - cocoa_pos != 1:
                    continue

                # Constraint 8: Avery in yellow house
                if houses[avery_pos]['color'] != 'yellow':
                    continue

                # Constraint 9: Rabbit owner not milk drinker
                for p in range(1, 5):
                    if houses[p]['pet'] == 'rabbit' and houses[p]['drink'] == 'milk':
                        valid = False
                        break
                if not valid:
                    continue

                # Found valid solution
                for p in range(1, 5):
                    if houses[p]['pet'] == 'bird':
                        print(f"ANSWER: {houses[p]['person']}")
                        exit()
